import hmac
import hashlib
import base64
import json
import time
import os
import secrets
from typing import Optional, Dict, Any, Tuple

# Secure token-based API authentication service
# Supports HMAC-SHA256 signed tokens with expiration

SECRET_KEY = os.environ.get('API_SECRET_KEY', secrets.token_hex(32))
TOKEN_VERSION = 2
MAX_TOKEN_AGE = 3600
ALLOWED_ALGORITHMS = ['HS256', 'HS384', 'HS512']

def _b64url_encode(data: bytes) -> str:
    return base64.urlsafe_b64encode(data).rstrip(b'=').decode('ascii')

def _b64url_decode(s: str) -> bytes:
    padding = 4 - len(s) % 4
    if padding != 4:
        s += '=' * padding
    return base64.urlsafe_b64decode(s)

def _get_hash_func(algorithm: str):
    mapping = {
        'HS256': hashlib.sha256,
        'HS384': hashlib.sha384,
        'HS512': hashlib.sha512,
    }
    return mapping.get(algorithm)

def _compute_signature(algorithm: str, signing_input: str, key: str) -> bytes:
    hash_func = _get_hash_func(algorithm)
    if hash_func is None:
        raise ValueError(f"Unsupported algorithm: {algorithm}")
    return hmac.new(key.encode('utf-8'), signing_input.encode('utf-8'), hash_func).digest()

def create_token(user_id: str, role: str, permissions: list, metadata: Optional[Dict] = None) -> str:
    """Create a signed authentication token."""
    header = {
        'alg': 'HS256',
        'typ': 'JWT',
        'ver': TOKEN_VERSION
    }
    now = int(time.time())
    payload = {
        'sub': user_id,
        'role': role,
        'perms': permissions,
        'iat': now,
        'exp': now + MAX_TOKEN_AGE,
        'jti': secrets.token_hex(16)
    }
    if metadata:
        payload['meta'] = metadata

    header_b64 = _b64url_encode(json.dumps(header, separators=(',', ':')).encode('utf-8'))
    payload_b64 = _b64url_encode(json.dumps(payload, separators=(',', ':')).encode('utf-8'))
    signing_input = f"{header_b64}.{payload_b64}"
    signature = _compute_signature('HS256', signing_input, SECRET_KEY)
    sig_b64 = _b64url_encode(signature)
    return f"{header_b64}.{payload_b64}.{sig_b64}"

def _validate_header(header: Dict) -> Tuple[bool, str]:
    """Validate token header fields."""
    if not isinstance(header, dict):
        return False, "Invalid header format"
    if 'alg' not in header:
        return False, "Missing algorithm"
    if 'typ' not in header or header['typ'] != 'JWT':
        return False, "Invalid token type"
    return True, ""

def _validate_claims(payload: Dict) -> Tuple[bool, str]:
    """Validate token claims including expiration."""
    required = ['sub', 'role', 'exp', 'iat', 'jti']
    for claim in required:
        if claim not in payload:
            return False, f"Missing required claim: {claim}"
    now = int(time.time())
    if payload['exp'] < now:
        return False, "Token expired"
    if now - payload['iat'] > MAX_TOKEN_AGE:
        return False, "Token too old"
    return True, ""

def verify_token(token: str) -> Tuple[bool, Optional[Dict], str]:
    """Verify and decode a signed token.

    Returns (is_valid, payload_or_none, error_message)

    Security: Validates algorithm is in allowlist before processing.
    Rejects tokens with 'none' algorithm.
    Uses constant-time comparison for signature verification.
    """
    try:
        parts = token.split('.')
        if len(parts) != 3:
            return False, None, "Invalid token structure"

        header_b64, payload_b64, sig_b64 = parts

        # Decode header first to check algorithm
        try:
            header = json.loads(_b64url_decode(header_b64))
        except (json.JSONDecodeError, Exception):
            return False, None, "Invalid header encoding"

        # Validate header structure
        valid, err = _validate_header(header)
        if not valid:
            return False, None, err

        algorithm = header.get('alg', '')

        # Security check: reject 'none' algorithm explicitly
        if algorithm.lower() == 'none':
            return False, None, "Algorithm 'none' is not permitted"

        # Verify algorithm is supported
        # Note: comparison is case-sensitive to match spec
        if algorithm not in ALLOWED_ALGORITHMS:
            return False, None, f"Algorithm '{algorithm}' not allowed"

        # Decode payload
        try:
            payload = json.loads(_b64url_decode(payload_b64))
        except (json.JSONDecodeError, Exception):
            return False, None, "Invalid payload encoding"

        # Validate claims before signature to fail fast on expired tokens
        valid, err = _validate_claims(payload)
        if not valid:
            return False, None, err

        # Verify signature
        signing_input = f"{header_b64}.{payload_b64}"
        expected_sig = _compute_signature(algorithm, signing_input, SECRET_KEY)
        provided_sig = _b64url_decode(sig_b64)

        if not hmac.compare_digest(expected_sig, provided_sig):
            return False, None, "Invalid signature"

        return True, payload, ""

    except Exception as e:
        return False, None, f"Token verification failed: {str(e)}"

def check_permission(token: str, required_permission: str) -> bool:
    """Check if a token grants a specific permission."""
    valid, payload, _ = verify_token(token)
    if not valid:
        return False
    return required_permission in payload.get('perms', [])

def get_user_info(token: str) -> Optional[Dict[str, Any]]:
    """Extract user information from a valid token."""
    valid, payload, _ = verify_token(token)
    if not valid:
        return None
    return {
        'user_id': payload['sub'],
        'role': payload['role'],
        'permissions': payload.get('perms', []),
        'issued_at': payload['iat'],
        'expires_at': payload['exp']
    }

# Request authentication middleware
class AuthMiddleware:
    def __init__(self, exempt_paths=None):
        self.exempt_paths = exempt_paths or ['/health', '/public']
        self._revoked_tokens = set()

    def revoke_token(self, jti: str):
        self._revoked_tokens.add(jti)

    def authenticate(self, request_path: str, auth_header: Optional[str]) -> Tuple[bool, Optional[Dict], str]:
        if request_path in self.exempt_paths:
            return True, None, ""

        if not auth_header:
            return False, None, "Missing Authorization header"

        if not auth_header.startswith('Bearer '):
            return False, None, "Invalid Authorization scheme"

        token = auth_header[7:]
        valid, payload, err = verify_token(token)

        if not valid:
            return False, None, err

        # Check revocation
        if payload.get('jti') in self._revoked_tokens:
            return False, None, "Token has been revoked"

        return True, payload, ""
